<x-eoffice::manajemen-praktikum.ui.admin-settings-styles />
@once
<style>
.mp-schedule-tabs{display:flex;gap:8px;border-bottom:1px solid var(--c-border);padding:0 20px;overflow-x:auto}.mp-schedule-tabs a{padding:14px 12px;white-space:nowrap;font-size:13px;font-weight:600;color:#666D80;text-decoration:none;border-bottom:2px solid transparent}.mp-schedule-tabs a[aria-current=page]{color:#0B266E;border-color:#0B266E}
.mp-calendar-body{padding:20px 24px}.mp-calendar-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:16px}.mp-calendar-date{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap}.mp-calendar-date>span{color:#0B266E;font-size:13px;font-weight:700}.mp-calendar-date .mp-input{width:145px;font-size:12px}.mp-calendar-filter{min-width:260px;max-width:100%}.mp-calendar-filter fieldset{display:flex;align-items:center;gap:8px;border:0;padding:0;margin:0;min-width:0}.mp-calendar-filter fieldset:disabled{opacity:.6}.mp-calendar-legend{display:flex;flex-wrap:wrap;gap:12px 18px;margin-bottom:16px;font-size:12px;color:#666D80}.mp-calendar-legend>span{display:flex;align-items:center;gap:6px}.mp-calendar-legend i{display:block;width:12px;height:12px;border-radius:3px;border:1px solid #DFE1E7}.mp-calendar-legend i[data-state=available]{background:#34D399}.mp-calendar-legend i[data-state=pending]{background:#FBBF24}.mp-calendar-legend i[data-state=occupied]{background:#C084FC}.mp-calendar-legend i[data-state=internal]{background:#60A5FA}.mp-calendar-legend i[data-state=draft]{background:#DBEAFE}.mp-calendar-legend i[data-state=closed],.mp-calendar-legend i[data-state=conflict]{background:#F87171}
.mp-calendar-scroll{overflow:auto;max-height:620px;border:1px solid #DFE1E7;border-radius:10px;margin:16px 0;scrollbar-gutter:stable}.mp-calendar-table{width:100%;table-layout:fixed;border-collapse:separate;border-spacing:0;font-size:12px}.mp-calendar-table th,.mp-calendar-table td{border-right:1px solid #E5E7EB;border-bottom:1px solid #E5E7EB;text-align:center;vertical-align:middle;overflow-wrap:anywhere}.mp-calendar-table thead th{padding:8px 6px;color:#666D80;background:#F8F9FB;font-size:11px;font-weight:600}.mp-calendar-table thead tr:first-child th{color:#0B266E;height:52px}.mp-calendar-table thead th strong,.mp-calendar-table thead th span{display:block}.mp-calendar-table thead th strong{font-size:13px}.mp-calendar-table thead th span{margin-top:3px;font-weight:500}.mp-calendar-table thead th[aria-current=date]{background:#EFF6FF}.mp-calendar-table .mp-calendar-time{position:sticky;left:0;z-index:2;width:72px;background:#F8F9FB;font-size:11px;font-weight:700;color:#374151;border-right:1px solid #D1D5DB}.mp-calendar-table td{padding:0}.mp-calendar-table tr:last-child>*{border-bottom:0}.mp-calendar-table tr>*:last-child{border-right:0}.mp-calendar-slot{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:100%;min-height:62px;padding:10px 8px;border:0;background:transparent;font:inherit;color:inherit;line-height:1.5}.mp-calendar-table td[data-state=available]{background:#ECFDF5;color:#047857}.mp-calendar-table td[data-state=pending]{background:#FFF9E6;color:#B45309}.mp-calendar-table td[data-state=occupied]{background:#F1E9FF;color:#6B21A8}.mp-calendar-table td[data-state=internal]{background:#EFF6FF;color:#1D4ED8}.mp-calendar-table td[data-state=draft]{background:#DBEAFE;color:#0B266E}.mp-calendar-table td[data-state=closed]{background:#F8F9FB;color:#808897}.mp-calendar-table td[data-state=conflict]{background:#FFF1F2;color:#9D174D}.mp-calendar-slot:is(button){cursor:pointer;transition:background .15s}.mp-calendar-slot:is(button):hover{background:rgba(11,38,110,.07)}.mp-calendar-slot:is(button):focus-visible{outline:2px solid #0B266E;outline-offset:-2px}.mp-calendar-slot:disabled{cursor:not-allowed;opacity:.65}.mp-calendar-booking{max-width:100%;font-size:11px}.mp-calendar-booking>span,.mp-calendar-booking>strong{display:block}.mp-calendar-booking>span:last-child{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.mp-calendar-caption{font-size:11px}.mp-calendar-pick{font-size:10px;font-weight:600}.mp-calendar-toolbar [aria-disabled=true]{opacity:.5;cursor:not-allowed}.mp-schedule-period{width:340px;max-width:100%}.mp-schedule-plan{scroll-margin-top:24px}
.mp-schedule-empty{margin:24px;padding:48px 24px;text-align:center;background:#F9FAFB;border:1px dashed #DFE1E7;border-radius:12px}.mp-schedule-empty>.mp-icon{width:40px;height:40px;margin:0 auto 16px;color:#9CA3AF}.mp-schedule-empty h3{margin:0 0 8px;font-size:16px;font-weight:700;color:#0D0D12}.mp-schedule-empty p{font-size:13px;color:#666D80;margin:0 auto 20px;max-width:440px;line-height:20px}.mp-schedule-list-tools{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.mp-schedule-search{position:relative;min-width:200px;flex:1}.mp-schedule-search>.mp-icon{position:absolute;left:12px;top:50%;transform:translateY(-50%);color:#808897}.mp-schedule-search input{padding-left:14px;width:100%;font-size:13px}.mp-schedule-summary{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;color:#666D80}.mp-schedule-status{display:inline-block;padding:3px 12px;border-radius:9999px;border:1px solid #E5E7EB;background:#F3F4F6;color:#374151;font-size:11px;font-weight:700;letter-spacing:.02em;text-transform:uppercase;white-space:nowrap}.mp-schedule-status[data-status=approved]{background:#ECFDF5;color:#047857;border-color:#A7F3D0}.mp-schedule-status[data-status=pending]{background:#FFF9E6;color:#B45309;border-color:#FFEBB3}.mp-schedule-status[data-status=rejected]{background:#FFF1F2;color:#9D174D;border-color:#FECDD3}
.mp-schedule-modal-mask{position:fixed;inset:0;z-index:9999;background:rgba(17,24,39,.4);display:flex;align-items:center;justify-content:center;padding:20px}.mp-schedule-modal{background:white;border:1px solid #DFE1E7;border-radius:16px;box-shadow:0 20px 50px rgba(0,0,0,.15);width:520px;max-width:100%;max-height:calc(100dvh - 40px);overflow:auto}.mp-schedule-modal-header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:20px 24px;border-bottom:1px solid #DFE1E7}.mp-schedule-modal-header h2{margin:0;font-size:16px;font-weight:700;color:#0D0D12}.mp-schedule-modal-header p{font-size:13px;color:#666D80;margin:6px 0 0}.mp-schedule-modal .mp-settings-footer{justify-content:flex-end}.mp-schedule-field-error{font-size:12px;color:#DF1C41;margin:0}
.mp-schedule-breadcrumb{display:flex;align-items:center;gap:8px;font-size:12px;color:#666D80}.mp-schedule-breadcrumb a{color:#666D80;text-decoration:none}.mp-schedule-breadcrumb a:hover{color:#0B266E}.mp-schedule-breadcrumb>span{color:#353849;font-weight:600}
.mp-calendar-filter{width:280px;min-width:0}.mp-calendar-legend i[data-state=closed]{background:#E5E7EB}.mp-calendar-scroll:focus-visible{outline:2px solid #0B266E;outline-offset:2px}
.mp-settings-card{min-width:0}.mp-schedule-period .ta-select>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.mp-room-calendar .mp-card-header>div:first-child{min-width:0}
.mp-calendar-table td.mp-calendar-hover{background-image:linear-gradient(rgba(11,38,110,.04),rgba(11,38,110,.04))}.mp-calendar-table td.mp-calendar-selected{background:#DDF2EE!important;color:#174E43!important;box-shadow:inset 2px 0 #40C4AA,inset -2px 0 #40C4AA;border-bottom-color:#DDF2EE}.mp-calendar-table td.mp-calendar-selected-start{border-radius:8px 8px 0 0;box-shadow:inset 2px 0 #40C4AA,inset -2px 0 #40C4AA,inset 0 2px #40C4AA}.mp-calendar-table td.mp-calendar-selected-end{border-radius:0 0 8px 8px;box-shadow:inset 2px 0 #40C4AA,inset -2px 0 #40C4AA,inset 0 -2px #40C4AA}.mp-calendar-table td.mp-calendar-selected-start.mp-calendar-selected-end{border-radius:8px;box-shadow:inset 0 0 0 2px #40C4AA}.mp-calendar-table td.mp-calendar-selected .mp-calendar-slot{background:transparent}.mp-calendar-table .mp-calendar-slot{user-select:none;-webkit-user-select:none}.mp-calendar-legend i[data-state=selected]{background:#40C4AA;border-color:#40C4AA}
.mp-calendar-note{min-height:76px;max-height:160px;resize:vertical;overflow-y:auto}.mp-calendar-note-count{text-align:right}
.mp-calendar-table td[data-state=available]{background:#fff}.mp-calendar-legend i[data-state=available]{background:#fff}
.mp-schedule-plan{border:1px solid var(--c-border);border-radius:12px;min-width:0;overflow:visible}.mp-schedule-plan>header{padding:16px 20px;display:flex;align-items:center;gap:12px;background:#F8F9FB;border-radius:11px}.mp-schedule-plan>header label{font-size:13px;font-weight:600;cursor:pointer}.mp-schedule-controls{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}.mp-schedule-controls>div{flex:1;min-width:150px}.mp-schedule-tasks{display:flex;gap:12px;flex-wrap:wrap;font-size:13px;color:#353849}.mp-schedule-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.mp-schedule-report{font-size:13px;color:#666D80;line-height:20px}.mp-schedule-report ul{margin:8px 0;padding-left:20px}.mp-schedule-history{margin:0;padding:0;list-style:none}.mp-schedule-history li{padding:14px 0;border-bottom:1px solid var(--c-border);font-size:13px;line-height:20px}.mp-schedule-history li:last-child{border-bottom:0}.mp-schedule-input{width:110px;min-width:90px}.mp-settings-table tr[data-conflict=true]{box-shadow:inset 3px 0 #DF1C41}.mp-schedule-actions .mp-btn:disabled{cursor:not-allowed}
@media(max-width:640px){.mp-schedule-plan>header{padding:16px}.mp-schedule-tabs{padding:0 8px}}
@media(max-width:768px){.mp-calendar-body{padding:16px}.mp-calendar-date{order:3;width:100%}.mp-calendar-date>span{width:100%;text-align:center}.mp-calendar-filter{width:100%}.mp-calendar-toolbar{gap:16px}.mp-calendar-toolbar>.mp-schedule-actions{margin-left:auto}.mp-schedule-list-tools{width:100%}.mp-schedule-list-tools>*{flex:1}.mp-schedule-empty{margin:16px;padding:32px 16px}}
</style>
<style>
.mp-calendar-draft-edit{width:100%;border:1px solid transparent;border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:11px;text-align:center;padding:6px;cursor:pointer;transition:background .15s,border-color .15s}.mp-calendar-draft-edit:hover{background:rgba(11,38,110,.09);border-color:#93B4E8}.mp-calendar-draft-edit:focus-visible{outline:2px solid #0B266E;outline-offset:2px}.mp-calendar-draft-edit:disabled{cursor:not-allowed;opacity:.6}
.mp-schedule-packages{min-width:1000px;table-layout:fixed}.mp-schedule-packages th:nth-child(2){width:34%}.mp-schedule-packages th:nth-child(3){width:24%}.mp-schedule-packages th:last-child{width:136px}.mp-schedule-packages td{overflow-wrap:anywhere;color:#353849}.mp-schedule-packages .mp-settings-name,.mp-schedule-practicum-list .mp-settings-name{font-size:14px;font-weight:600;line-height:21px;color:#353849;white-space:normal;overflow-wrap:anywhere}.mp-schedule-packages .mp-settings-email,.mp-schedule-practicum-list .mp-settings-email{font-size:12px;line-height:18px;color:#666D80;margin-top:4px}.mp-schedule-practicums{display:grid;gap:6px;margin-bottom:6px}.mp-schedule-more{justify-self:start;padding:2px 0;border:0;background:transparent;color:#0B266E;font:inherit;font-size:12px;font-weight:600;cursor:pointer}.mp-schedule-more:hover{text-decoration:underline}.mp-schedule-more:focus-visible{outline:2px solid #0B266E;outline-offset:3px;border-radius:3px}.mp-schedule-counts{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.mp-schedule-counts .mp-badge{white-space:nowrap}.mp-schedule-practicum-list{list-style:none;padding:0;margin:0;overflow-y:auto;max-height:min(55dvh,420px)}.mp-schedule-practicum-list li{padding:16px 24px;border-bottom:1px solid #DFE1E7}.mp-schedule-practicum-list li:last-child{border-bottom:0}.mp-schedule-practicum-list .mp-schedule-counts{margin-top:8px}
</style>
@endonce
@once
<style>
.mp-calendar-table td.mp-calendar-hover{background-image:none}.mp-calendar-table td[data-pickable=true]:hover{background-color:#EEF1F8}.mp-calendar-slot:is(button):hover{background:transparent}.mp-calendar-table td[data-pickable=true]{position:relative}.mp-calendar-table td[data-pickable=true]>.mp-calendar-slot{position:absolute;inset:0;height:100%;min-height:0}.mp-calendar-table tbody tr{height:76px}.mp-schedule-time-select{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:6px;min-width:0}.mp-schedule-time-select>div{min-width:0}.mp-schedule-time-select>.ta-select{min-width:0}.mp-schedule-time-select>span{color:#666D80;font-size:14px}.mp-slot-help{margin:6px 0 0;font-size:13px;line-height:20px;color:#666D80}
</style>
@endonce
